	public CharacterSFXData CharacterSFXData => characterSFXData;

	private string GetLocalizedString(string id)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(id);
	}

	public int GetCharacterLevel()
	{
		return CharacterProgression.GetCharacterLevel(this);
	}

	public bool IsStartingStarBlessingAndDiceUnlocked()
	{
		return GetCharacterLevel() > 0;
	}

	public int GetCharacterCurrentLevelXP(int characterLevel)
	{
		return CharacterProgression.GetCharacterCurrentLevelXP(characterLevel);
	}

	public int GetCharacterNextLevelXP(int characterLevel)
	{
		return CharacterProgression.GetCharacterNextLevelXP(characterLevel);
	}

	public List<DiceFace> GetLockedDiceFaces()
	{
		return CharacterProgression.GetLockedDiceFaces(this);
	}

	public List<string> GetLockedDiceNames()
	{
		return CharacterProgression.GetLockedDiceNames(this);
	}

	public List<OmenData> GetLockedOmenDatas()
	{
		return CharacterProgression.GetLockedOmenDatas(this);
	}

	public float GetCharacterNonNeutralPercentage()
	{
		return CharacterProgression.GetCharacterNonNeutralPercentage(this);
	}

	public void SetCharacterPercentageProgression()
	{
		CharacterProgression.SetCharacterPercentageProgression(this);
	}
